CREATE TABLE public.campus_permissions (user_id uuid NOT NULL, capability text NOT NULL CHECK (capability IN ('admin','faculty','security')), PRIMARY KEY(user_id,capability));
GRANT SELECT ON public.campus_permissions TO authenticated; GRANT ALL ON public.campus_permissions TO service_role;
ALTER TABLE public.campus_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own capabilities" ON public.campus_permissions FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.campus_capability(cap text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.campus_permissions WHERE user_id=auth.uid() AND capability IN (cap,'admin')) OR (cap IN ('admin','faculty') AND public.has_role(auth.uid(),'campus_manager')) $$;
REVOKE ALL ON FUNCTION public.campus_capability(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.campus_capability(text) TO authenticated,service_role;
CREATE TABLE public.campus_notices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 150),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 5000),category text NOT NULL CHECK(category IN ('University','Department','Academic','Examination','Event','Emergency')),department text NOT NULL DEFAULT '',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.campus_notices TO authenticated; GRANT ALL ON public.campus_notices TO service_role;
ALTER TABLE public.campus_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read notices" ON public.campus_notices FOR SELECT TO authenticated USING(true);
CREATE POLICY "approved publish notices" ON public.campus_notices FOR INSERT TO authenticated WITH CHECK(public.campus_capability('admin') AND created_by=auth.uid());
CREATE POLICY "approved edit notices" ON public.campus_notices FOR UPDATE TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin'));
CREATE POLICY "approved delete notices" ON public.campus_notices FOR DELETE TO authenticated USING(public.campus_capability('admin'));
CREATE TABLE public.notice_reads (notice_id uuid NOT NULL REFERENCES public.campus_notices(id) ON DELETE CASCADE,user_id uuid NOT NULL DEFAULT auth.uid(),read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(notice_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.notice_reads TO authenticated; GRANT ALL ON public.notice_reads TO service_role;
ALTER TABLE public.notice_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notice reads" ON public.notice_reads FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.campus_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',kind text NOT NULL DEFAULT 'Announcement',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.campus_notifications TO authenticated; GRANT ALL ON public.campus_notifications TO service_role;
ALTER TABLE public.campus_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notification read" ON public.campus_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "own notification update" ON public.campus_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.notify_campus_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.campus_notifications(user_id,title,body,kind) SELECT id,NEW.title,left(NEW.body,500),NEW.category FROM public.profiles; RETURN NEW; END $$;
CREATE TRIGGER notify_campus_notice AFTER INSERT ON public.campus_notices FOR EACH ROW EXECUTE FUNCTION public.notify_campus_notice();